let config={},state={},setup={},powerSensors=[],socSensors=[],energySensors=[],selected=[],currentTab='dashboard',formLoaded=false,socPlan='middle',datesEdited=false;
const titles={dashboard:['Energy overview','Consumption, solar and battery forecasts.'],datasets:['Models','Prepare history, train a candidate, then review the results.'],settings:['Settings','Home Assistant, solar panels, battery and charging schedules.']};
