  title=m.hoursAxis?row.hours+'-hour forecast':new Date(time).toLocaleString('en-AU',{timeZone:config.timezone,day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',hour12:false});
  const labels={actual:'Actual',predicted:'Predicted',baseline:'Existing model',candidate:'Candidate',value:'Recorded value'};
