  let xx=meta.useTime?meta.l+(time-meta.start)*(meta.w-meta.l-meta.r)/(meta.end-meta.start):meta.l+i*(meta.w-meta.l-meta.r)/Math.max(1,meta.rows.length-1);
  layer.style.display='';let cursor=layer.querySelector('.chart-cursor');cursor.setAttribute('x1',xx);cursor.setAttribute('x2',xx);
